using System;using System.Collections.Generic;using System.Linq;using System.Text.RegularExpressions;using System.Threading;using System.Threading.Tasks;using KGV.Core.Interfaces;using KGV.Core.Models;
namespace KGV.Core.Utilities;
public static class SerienbriefPdfFactory
{
 private static readonly string[] Required={"empfaenger_vorname","empfaenger_nachname","empfaenger_strasse","empfaenger_plz","empfaenger_ort","betreff","briefanrede","brieftext"};
 public static async Task<(IReadOnlyList<SerienbriefPdfResult> Results,string? GlobalError)> RenderAsync(IReadOnlyList<SerienbriefPdfRenderJob> jobs,IPdfTemplateProvider provider,CancellationToken cancellationToken=default)
 { try { var template=await provider.GetActiveAsync(new PdfTemplateRequest("briefbogen-allgemein","briefbogen-allgemein-field-spec/v2","top-left/v1"),cancellationToken);var names=template.Fields.Select(x=>x.Name).ToHashSet(StringComparer.OrdinalIgnoreCase);var missing=Required.Where(x=>!names.Contains(x)).ToArray();if(missing.Length>0)return (Array.Empty<SerienbriefPdfResult>(),$"Briefbogenfelder fehlen: {string.Join(", ",missing)}");var result=new List<SerienbriefPdfResult>();var used=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(var job in jobs){try{var file=UniqueFileName(job,used);var values=new Dictionary<string,string>{{"empfaenger_vorname",job.Vorname},{"empfaenger_nachname",job.Nachname},{"empfaenger_strasse",job.Strasse},{"empfaenger_plz",job.Plz},{"empfaenger_ort",job.Ort},{"betreff",job.Betreff},{"briefanrede",job.Briefanrede},{"brieftext",ToText(job.HtmlInhalt)}};result.Add(new(job.RowKey,job.MitgliedId,job.ParzelleId,file,PdfTemplateRenderer.Render(template.PdfBytes,template.Fields,values),null));}catch(Exception ex){result.Add(new(job.RowKey,job.MitgliedId,job.ParzelleId,"",null,ex.Message));}}return(result,null);}catch(Exception ex){return(Array.Empty<SerienbriefPdfResult>(),$"Briefbogen konnte nicht geladen werden: {ex.Message}");}}
 public static string ToText(string html)=>Regex.Replace(Regex.Replace(html??"",@"<\s*br\s*/?>|</p\s*>","\n",RegexOptions.IgnoreCase),@"<[^>]+>","").Trim();
 private static string UniqueFileName(SerienbriefPdfRenderJob job,HashSet<string> used){var baseName=$"{job.Datum}_{job.DateinameKontext}.pdf";var name=baseName;var i=2;while(!used.Add(name))name=$"{baseName[..^4]}_{i++}.pdf";return name;}
}
